/* Shared retro character-sheet expandable module system.
   Used by every HTML page in the Universal Project AI Directory. */
:root{
  --retro-module-blue:#003399;
  --retro-module-blue-light:#2FBED8;
  --retro-module-soft:#6699cc;
  --retro-module-cyan:#00FFFF;
  --retro-module-cyan-dark:#00BFAF;
  --retro-module-orange:#CA6309;
  --retro-module-orange-light:#F7B36B;
  --retro-module-paper:rgba(239,251,255,.97);
  --retro-module-paper-warm:rgba(255,243,232,.97);
  --retro-module-ink:#1A0A02;
  --retro-module-shadow:0 3px 0 rgba(0,0,0,.55),0 14px 35px rgba(0,0,0,.35);
}
.retro-character-module{
  min-width:0;
  border:2px solid var(--retro-module-blue)!important;
  background:var(--retro-module-paper);
  color:var(--retro-module-ink);
  box-shadow:var(--retro-module-shadow);
  scroll-margin-top:115px;
  overflow:visible;
}
.retro-character-module > .retro-character-module-hd{
  order:-9999;
  grid-column:1/-1;
  flex:0 0 100%;
  width:100%;
  min-width:0;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:10px;
  padding:6px 8px;
  color:#fff;
  border-bottom:2px solid #001E24;
  background:linear-gradient(90deg,var(--retro-module-blue),var(--retro-module-blue-light),var(--retro-module-orange));
  box-shadow:inset 1px 1px rgba(255,255,255,.28);
}
.retro-character-module-hd .retro-character-module-title{
  min-width:0;
  margin:0;
  font:900 13px/1.2 Verdana,Arial,Helvetica,sans-serif;
  letter-spacing:.02em;
  text-transform:uppercase;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
  color:#fff;
  text-shadow:1px 1px #000,0 0 7px var(--retro-module-cyan);
}
.retro-character-module-hd .retro-character-module-title::before{
  content:'✦';
  margin-right:7px;
  color:#FFF7D1;
  text-shadow:0 0 6px var(--retro-module-cyan);
}
.retro-character-module-toggle{
  flex:0 0 auto;
  min-width:32px!important;
  width:32px;
  min-height:26px!important;
  height:26px;
  margin:0!important;
  padding:1px 6px!important;
  border:1px solid #000!important;
  border-radius:4px!important;
  color:#001E24!important;
  background:linear-gradient(#ECFFFF,var(--retro-module-cyan) 55%,#008C96)!important;
  box-shadow:inset 1px 1px #fff,2px 2px 0 #003C42!important;
  font:900 15px/1 Verdana,Arial,sans-serif!important;
  cursor:pointer!important;
}
.retro-character-module.is-retro-collapsed > :not(.retro-character-module-hd){
  display:none!important;
}
.retro-character-module.is-retro-collapsed{
  min-height:0!important;
  height:auto!important;
}
.retro-character-module.is-retro-collapsed > .retro-character-module-hd{
  border-bottom:0;
}
.retro-character-module-hd:focus-within{
  outline:3px solid var(--retro-module-cyan);
  outline-offset:2px;
}

/* Floating navigation copied from the retro character-sheet interaction pattern. */
.retro-module-nav{
  position:fixed;
  left:12px;
  top:130px;
  width:72px;
  height:72px;
  z-index:25000;
  user-select:none;
}
.retro-module-nav-toggle{
  width:72px!important;
  height:72px!important;
  min-height:72px!important;
  padding:0!important;
  border-radius:50%!important;
  display:flex!important;
  flex-direction:column;
  align-items:center;
  justify-content:center;
  gap:1px;
  color:#001E24!important;
  border:3px double #FFF7D1!important;
  background:radial-gradient(circle at 30% 20%,#E8FFFF,var(--retro-module-cyan) 46%,var(--retro-module-blue) 84%)!important;
  box-shadow:0 0 0 3px rgba(0,51,153,.85),0 8px 24px rgba(0,0,0,.45),0 0 18px rgba(0,255,255,.75)!important;
  cursor:grab!important;
}
.retro-module-nav-toggle:active{cursor:grabbing!important}
.retro-module-nav-toggle b{font-size:22px;line-height:1}
.retro-module-nav-toggle span{font:900 8px/1.05 Verdana,Arial,sans-serif;letter-spacing:.06em;text-transform:uppercase}
.retro-module-nav-panel{
  display:none;
  position:absolute;
  left:80px;
  top:0;
  width:270px;
  padding:10px;
  border:3px double var(--retro-module-cyan-dark);
  color:var(--retro-module-ink);
  background:linear-gradient(180deg,rgba(232,255,255,.99),rgba(255,243,232,.98));
  box-shadow:0 12px 32px rgba(0,0,0,.48);
}
.retro-module-nav.is-open .retro-module-nav-panel{display:block}
.retro-module-nav-panel label{display:block;margin:0 0 5px;color:#003C42;font-weight:900}
.retro-module-nav-panel select{width:100%;margin:0 0 8px;padding:5px;border:1px solid #275859;background:#fff;color:#1A0A02}
.retro-module-nav-actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px}
.retro-module-nav-actions button{min-width:0!important;font-size:10px!important;padding:5px!important}
.retro-module-nav-go{grid-column:1/-1}
.retro-module-nav-hint{display:block;margin-top:7px;color:#7A3A07;font-size:9px;line-height:1.3;font-weight:700}

/* Existing directory modules receive the same character-sheet header treatment. */
.module.retro-character-module > .module-hd{
  background:linear-gradient(90deg,var(--retro-module-blue),var(--retro-module-blue-light),var(--retro-module-orange))!important;
  border-bottom:2px solid #001E24!important;
}
.module.retro-character-module > .module-hd h2{
  color:#fff!important;
  text-shadow:1px 1px #000,0 0 7px var(--retro-module-cyan)!important;
}
.module.retro-character-module.collapsed > .module-hd{border-bottom:0!important}

@media(max-width:850px){
  .retro-module-nav{left:8px;top:96px}
  .retro-module-nav-panel{left:0;top:80px;width:min(270px,calc(100vw - 18px))}
}
@media print{
  .retro-module-nav,.retro-character-module-toggle{display:none!important}
  .retro-character-module.is-retro-collapsed > :not(.retro-character-module-hd){display:initial!important}
  .retro-character-module{box-shadow:none!important;break-inside:avoid}
}

:root {
  --paint-rgb: 49 87 164;
  --paper-rgb: 244 240 226;
  --texture-intensity: 0.72;
  --texture-scale: 1;
  --texture-angle: 18deg;
}

/* Every texture is generated with CSS gradients and variables. No image files are used. */
.studio-texture {
  background-color: rgb(var(--paper-rgb));
  background-blend-mode: multiply, normal, normal, normal;
  isolation: isolate;
}

.texture-canvas-weave {
  background-image:
    repeating-linear-gradient(0deg,
      rgb(var(--paint-rgb) / calc(.035 * var(--texture-intensity))) 0,
      rgb(var(--paint-rgb) / calc(.035 * var(--texture-intensity))) calc(1px * var(--texture-scale)),
      transparent calc(1px * var(--texture-scale)),
      transparent calc(4px * var(--texture-scale))),
    repeating-linear-gradient(90deg,
      rgb(53 43 30 / calc(.055 * var(--texture-intensity))) 0,
      rgb(53 43 30 / calc(.055 * var(--texture-intensity))) calc(1px * var(--texture-scale)),
      transparent calc(1px * var(--texture-scale)),
      transparent calc(5px * var(--texture-scale))),
    linear-gradient(135deg, rgb(var(--paper-rgb)), rgb(var(--paper-rgb) / .88));
}

.texture-cold-press {
  background-image:
    radial-gradient(circle at 18% 22%, rgb(75 60 42 / calc(.11 * var(--texture-intensity))) 0 1px, transparent 1.5px),
    radial-gradient(circle at 67% 36%, rgb(255 255 255 / calc(.72 * var(--texture-intensity))) 0 1.2px, transparent 2px),
    radial-gradient(circle at 42% 78%, rgb(61 48 35 / calc(.08 * var(--texture-intensity))) 0 1px, transparent 1.8px),
    repeating-linear-gradient(11deg, transparent 0 8px, rgb(100 86 65 / calc(.025 * var(--texture-intensity))) 8px 9px),
    linear-gradient(145deg, rgb(var(--paper-rgb)), rgb(var(--paper-rgb) / .9));
  background-size:
    calc(17px * var(--texture-scale)) calc(19px * var(--texture-scale)),
    calc(23px * var(--texture-scale)) calc(29px * var(--texture-scale)),
    calc(31px * var(--texture-scale)) calc(21px * var(--texture-scale)),
    calc(45px * var(--texture-scale)) calc(45px * var(--texture-scale)),
    auto;
}

.texture-hot-press {
  background-image:
    radial-gradient(circle at 25% 25%, rgb(90 76 56 / calc(.045 * var(--texture-intensity))) 0 .7px, transparent 1.2px),
    radial-gradient(circle at 72% 68%, rgb(255 255 255 / calc(.5 * var(--texture-intensity))) 0 .8px, transparent 1.4px),
    linear-gradient(145deg, rgb(var(--paper-rgb)), rgb(var(--paper-rgb) / .94));
  background-size:
    calc(14px * var(--texture-scale)) calc(17px * var(--texture-scale)),
    calc(21px * var(--texture-scale)) calc(19px * var(--texture-scale)),
    auto;
}

.texture-chalk-soft {
  background-color: rgb(var(--paint-rgb) / .74);
  background-image:
    radial-gradient(circle, rgb(255 255 255 / calc(.42 * var(--texture-intensity))) 0 .7px, transparent 1.3px),
    radial-gradient(circle, rgb(25 20 18 / calc(.22 * var(--texture-intensity))) 0 .55px, transparent 1.2px),
    repeating-linear-gradient(var(--texture-angle), transparent 0 5px, rgb(255 255 255 / calc(.075 * var(--texture-intensity))) 5px 6px),
    linear-gradient(105deg, rgb(var(--paint-rgb) / .74), rgb(var(--paint-rgb) / .88));
  background-size:
    calc(7px * var(--texture-scale)) calc(9px * var(--texture-scale)),
    calc(11px * var(--texture-scale)) calc(8px * var(--texture-scale)),
    calc(17px * var(--texture-scale)) calc(17px * var(--texture-scale)),
    auto;
}

.texture-chalk-dense {
  background-color: rgb(var(--paint-rgb) / .9);
  background-image:
    radial-gradient(circle at 20% 30%, rgb(255 255 255 / calc(.33 * var(--texture-intensity))) 0 1px, transparent 1.8px),
    radial-gradient(circle at 80% 66%, rgb(20 16 14 / calc(.28 * var(--texture-intensity))) 0 .8px, transparent 1.5px),
    repeating-linear-gradient(calc(var(--texture-angle) + 13deg), transparent 0 3px, rgb(255 255 255 / calc(.09 * var(--texture-intensity))) 3px 4px),
    linear-gradient(92deg, rgb(var(--paint-rgb) / .82), rgb(var(--paint-rgb)));
  background-size:
    calc(6px * var(--texture-scale)) calc(7px * var(--texture-scale)),
    calc(9px * var(--texture-scale)) calc(12px * var(--texture-scale)),
    calc(13px * var(--texture-scale)) calc(13px * var(--texture-scale)),
    auto;
}

.texture-marker-streak {
  background-color: rgb(var(--paint-rgb) / .58);
  background-image:
    repeating-linear-gradient(var(--texture-angle),
      rgb(var(--paint-rgb) / calc(.24 * var(--texture-intensity))) 0 calc(5px * var(--texture-scale)),
      rgb(255 255 255 / calc(.08 * var(--texture-intensity))) calc(5px * var(--texture-scale)) calc(7px * var(--texture-scale)),
      rgb(var(--paint-rgb) / calc(.15 * var(--texture-intensity))) calc(7px * var(--texture-scale)) calc(13px * var(--texture-scale))),
    linear-gradient(90deg, rgb(var(--paint-rgb) / .46), rgb(var(--paint-rgb) / .72));
  background-blend-mode: multiply, normal;
}

.texture-marker-overlap {
  background-color: rgb(var(--paint-rgb) / .52);
  background-image:
    linear-gradient(90deg, transparent 0 19%, rgb(var(--paint-rgb) / calc(.34 * var(--texture-intensity))) 19% 38%, transparent 38% 55%, rgb(var(--paint-rgb) / calc(.38 * var(--texture-intensity))) 55% 76%, transparent 76%),
    repeating-linear-gradient(var(--texture-angle),
      transparent 0 calc(7px * var(--texture-scale)),
      rgb(255 255 255 / calc(.085 * var(--texture-intensity))) calc(7px * var(--texture-scale)) calc(9px * var(--texture-scale))),
    linear-gradient(90deg, rgb(var(--paint-rgb) / .44), rgb(var(--paint-rgb) / .7));
  background-blend-mode: multiply, screen, normal;
}

.texture-watercolor-wash {
  background-color: rgb(246 242 229);
  background-image:
    radial-gradient(ellipse at 28% 34%, rgb(var(--paint-rgb) / calc(.62 * var(--texture-intensity))) 0 26%, transparent 58%),
    radial-gradient(ellipse at 72% 62%, rgb(var(--paint-rgb) / calc(.48 * var(--texture-intensity))) 0 23%, transparent 61%),
    radial-gradient(ellipse at 54% 42%, rgb(255 255 255 / calc(.3 * var(--texture-intensity))) 0 12%, transparent 46%),
    repeating-radial-gradient(circle at 52% 50%, transparent 0 calc(6px * var(--texture-scale)), rgb(var(--paint-rgb) / calc(.035 * var(--texture-intensity))) calc(7px * var(--texture-scale)) calc(8px * var(--texture-scale))),
    linear-gradient(145deg, #f8f3e5, #e7ddca);
  background-blend-mode: multiply, multiply, screen, multiply, normal;
}

.texture-watercolor-bloom {
  background-color: rgb(247 243 230);
  background-image:
    radial-gradient(circle at 28% 42%, transparent 0 18%, rgb(var(--paint-rgb) / calc(.6 * var(--texture-intensity))) 20% 24%, rgb(var(--paint-rgb) / calc(.24 * var(--texture-intensity))) 28% 45%, transparent 67%),
    radial-gradient(circle at 66% 56%, rgb(255 255 255 / calc(.25 * var(--texture-intensity))) 0 11%, rgb(var(--paint-rgb) / calc(.58 * var(--texture-intensity))) 17% 21%, rgb(var(--paint-rgb) / calc(.22 * var(--texture-intensity))) 28% 48%, transparent 70%),
    radial-gradient(circle at 48% 25%, rgb(var(--paint-rgb) / calc(.24 * var(--texture-intensity))) 0 20%, transparent 55%),
    linear-gradient(145deg, #faf5e8, #e5dbc8);
  background-blend-mode: multiply, multiply, multiply, normal;
}

.texture-watercolor-granulation {
  background-color: rgb(244 239 224);
  background-image:
    radial-gradient(circle, rgb(var(--paint-rgb) / calc(.42 * var(--texture-intensity))) 0 .8px, transparent 1.4px),
    radial-gradient(circle at 70% 30%, rgb(var(--paint-rgb) / calc(.22 * var(--texture-intensity))) 0 1.2px, transparent 2.2px),
    radial-gradient(ellipse at 50% 50%, rgb(var(--paint-rgb) / calc(.48 * var(--texture-intensity))) 0 34%, transparent 74%),
    linear-gradient(145deg, #f8f2e1, #e4dac6);
  background-size:
    calc(5px * var(--texture-scale)) calc(7px * var(--texture-scale)),
    calc(11px * var(--texture-scale)) calc(13px * var(--texture-scale)),
    auto,
    auto;
  background-blend-mode: multiply, multiply, multiply, normal;
}

.texture-acrylic-smooth {
  background-color: rgb(var(--paint-rgb));
  background-image:
    repeating-linear-gradient(var(--texture-angle),
      rgb(255 255 255 / calc(.095 * var(--texture-intensity))) 0 calc(1px * var(--texture-scale)),
      transparent calc(1px * var(--texture-scale)) calc(5px * var(--texture-scale)),
      rgb(15 12 10 / calc(.065 * var(--texture-intensity))) calc(5px * var(--texture-scale)) calc(6px * var(--texture-scale))),
    linear-gradient(110deg, rgb(255 255 255 / calc(.09 * var(--texture-intensity))), transparent 35%, rgb(0 0 0 / calc(.09 * var(--texture-intensity))));
  background-blend-mode: overlay, multiply;
}

.texture-acrylic-impasto {
  background-color: rgb(var(--paint-rgb));
  background-image:
    repeating-linear-gradient(calc(var(--texture-angle) - 8deg),
      rgb(255 255 255 / calc(.28 * var(--texture-intensity))) 0 calc(1px * var(--texture-scale)),
      transparent calc(2px * var(--texture-scale)) calc(6px * var(--texture-scale)),
      rgb(0 0 0 / calc(.2 * var(--texture-intensity))) calc(7px * var(--texture-scale)) calc(9px * var(--texture-scale))),
    repeating-linear-gradient(calc(var(--texture-angle) + 22deg),
      transparent 0 calc(11px * var(--texture-scale)),
      rgb(255 255 255 / calc(.12 * var(--texture-intensity))) calc(11px * var(--texture-scale)) calc(13px * var(--texture-scale))),
    linear-gradient(125deg, rgb(255 255 255 / .12), transparent 42%, rgb(0 0 0 / .16));
  background-blend-mode: overlay, screen, multiply;
}

.texture-dry-brush {
  background-color: rgb(245 240 225);
  background-image:
    repeating-linear-gradient(var(--texture-angle),
      transparent 0 calc(3px * var(--texture-scale)),
      rgb(var(--paint-rgb) / calc(.78 * var(--texture-intensity))) calc(3px * var(--texture-scale)) calc(5px * var(--texture-scale)),
      transparent calc(5px * var(--texture-scale)) calc(9px * var(--texture-scale))),
    radial-gradient(ellipse at 50% 50%, rgb(var(--paint-rgb) / calc(.62 * var(--texture-intensity))) 0 29%, transparent 73%),
    linear-gradient(145deg, #f8f2e3, #e1d6c2);
  background-blend-mode: multiply, multiply, normal;
}

.texture-stipple {
  background-color: rgb(245 240 225);
  background-image:
    radial-gradient(circle, rgb(var(--paint-rgb) / calc(.85 * var(--texture-intensity))) 0 calc(1px * var(--texture-scale)), transparent calc(1.4px * var(--texture-scale))),
    radial-gradient(circle, rgb(var(--paint-rgb) / calc(.55 * var(--texture-intensity))) 0 calc(.7px * var(--texture-scale)), transparent calc(1.2px * var(--texture-scale))),
    linear-gradient(145deg, #f8f2e3, #e4dac6);
  background-size:
    calc(9px * var(--texture-scale)) calc(11px * var(--texture-scale)),
    calc(13px * var(--texture-scale)) calc(17px * var(--texture-scale)),
    auto;
  background-position: 0 0, 4px 7px, 0 0;
}

.texture-crosshatch {
  background-color: rgb(245 240 225);
  background-image:
    repeating-linear-gradient(35deg, transparent 0 calc(5px * var(--texture-scale)), rgb(var(--paint-rgb) / calc(.62 * var(--texture-intensity))) calc(5px * var(--texture-scale)) calc(6px * var(--texture-scale))),
    repeating-linear-gradient(-42deg, transparent 0 calc(7px * var(--texture-scale)), rgb(var(--paint-rgb) / calc(.46 * var(--texture-intensity))) calc(7px * var(--texture-scale)) calc(8px * var(--texture-scale))),
    linear-gradient(145deg, #f8f2e3, #e3d8c4);
  background-blend-mode: multiply, multiply, normal;
}

.texture-metallic {
  background-color: rgb(var(--paint-rgb));
  background-image:
    radial-gradient(circle, rgb(255 255 255 / calc(.62 * var(--texture-intensity))) 0 .7px, transparent 1.5px),
    radial-gradient(circle, rgb(0 0 0 / calc(.3 * var(--texture-intensity))) 0 .5px, transparent 1.2px),
    linear-gradient(115deg, rgb(255 255 255 / .36), transparent 27%, rgb(255 255 255 / .1) 45%, rgb(0 0 0 / .18) 72%, rgb(255 255 255 / .24));
  background-size:
    calc(7px * var(--texture-scale)) calc(9px * var(--texture-scale)),
    calc(11px * var(--texture-scale)) calc(13px * var(--texture-scale)),
    auto;
  background-blend-mode: screen, multiply, overlay;
}

.texture-fluorescent {
  background-color: rgb(var(--paint-rgb));
  background-image:
    radial-gradient(circle at 45% 42%, rgb(255 255 255 / calc(.38 * var(--texture-intensity))) 0 8%, transparent 42%),
    linear-gradient(135deg, rgb(255 255 255 / .22), transparent 40%, rgb(0 0 0 / .08));
  box-shadow:
    inset 0 0 22px rgb(255 255 255 / calc(.18 * var(--texture-intensity))),
    0 0 calc(18px * var(--texture-intensity)) rgb(var(--paint-rgb) / .45);
  filter: saturate(1.45) brightness(1.08);
}

